parameters.jsCode:
// COMPOSITION DES FAITS — entièrement par le code, c'est le cœur du régime :
// le modèle ne verra QUE cette liste numérotée. Chaque fait est figé avec
// son libellé, sa valeur et sa provenance ; le modèle citera des codes [Fn],
// jamais des chiffres à lui. Leçon des 38 rejets du commentaire exécutif.
const faits = [];
for (const m of $('Lire les faits indicateurs').all().map(x => x.json)) {
  const g = m.glissement_annuel_pct !== null ? `${m.glissement_annuel_pct > 0 ? '+' : ''}${m.glissement_annuel_pct} % sur un an` : 'glissement indisponible';
  faits.push({
    code: 'F' + (faits.length + 1),
    texte: `[${m.sector_code}] ${m.indicator_id} · ${m.indicator_label} : ${m.value} ${m.unit || ''} (${m.geo}, ${m.period}), ${g}${m.franchissement === 'franchi' ? ', amplitude inhabituelle pour cette série' : ''}`,
    source: { indicator_id: m.indicator_id, geo: m.geo, period: m.period, value: m.value, glissement: m.glissement_annuel_pct, statut: m.validation_status }
  });
}
for (const e of $('Lire les faits événements').all().map(x => x.json).filter(e => e && e.sector_code)) {
  faits.push({
    code: 'F' + (faits.length + 1),
    texte: `[${e.sector_code}] flux ${e.mois} : ${e.n} événement(s) de type ${e.type_evenement} lus dans la presse professionnelle (lecture IA non relue)`,
    source: { evenements: true, sector: e.sector_code, mois: e.mois, type: e.type_evenement, n: e.n }
  });
}
if (faits.length < 10) throw new Error('Trop peu de faits composés (' + faits.length + ') — lecture transversale sans matière.');
const consigne = `Tu es un analyste de veille économique pour un sous-traitant suisse de mécanique de précision (horlogerie, médical, automobile, aérospatial). Voici des FAITS numérotés, calculés depuis un registre vérifié. Ta seule tâche : proposer entre 3 et 6 HYPOTHÈSES DE LIAISON entre des faits de séries ou de secteurs DIFFÉRENTS — des cohérences, des contradictions, des mécanismes de transmission vers la sous-traitance.

Réponds STRICTEMENT en JSON, sans texte autour :
{"hypotheses":[{"enonce":"…","faits":["F3","F17"],"confiance":"moyenne","infirmable_par":"quelle donnée future confirmerait ou infirmerait"}]}

Règles impératives :
- N'écris AUCUN chiffre, AUCUN pourcentage, AUCUNE date dans l'énoncé : désigne les faits par leur code [Fn] — le lecteur verra les valeurs à côté.
- Chaque hypothèse cite AU MOINS deux faits, d'indicateurs ou de secteurs différents.
- Une hypothèse est une LECTURE possible, pas une certitude : formule-la comme telle.
- confiance parmi : haute, moyenne, basse. Style : phrases simples, sans tiret cadratin (—), ponctuation ordinaire. Une contradiction entre faits vaut une hypothèse à part entière.`;
return [{ json: {
  consigne,
  charge: faits.map(f => `${f.code} · ${f.texte}`).join('\n'),
  faits_index: Object.fromEntries(faits.map(f => [f.code, { texte: f.texte, source: f.source }])),
  run_id: $('Ouvrir le run').first().json.run_id
} }];

