parameters.jsCode:
// CONTRÔLES : faits cités existants, énoncé SANS chiffre étranger (tout
// chiffre est un incident — les valeurs vivent dans les faits cités, pas
// dans la prose), figeage des faits cités pour l'audit.
function texte(x) {
  if (Array.isArray(x.content)) return x.content.filter(b => b.type === 'text').map(b => b.text).join('');
  if (Array.isArray(x.candidates)) return ((x.candidates[0] || {}).content?.parts || []).filter(p => p.text).map(p => p.text).join('');
  return '';
}
const prep = $('Composer les faits').first().json;
let d;
try { d = JSON.parse(String(texte($input.first().json)).replace(/^```json/i, '').replace(/^```/, '').replace(/```$/, '').trim()); }
catch (e) { throw new Error('Réponse du modèle illisible : ' + String(e.message).slice(0, 80)); }
const sorties = [];
for (const h of (d.hypotheses || [])) {
  const incidents = [];
  const cites = (h.faits || []).filter(c => prep.faits_index[c]);
  const inconnus = (h.faits || []).filter(c => !prep.faits_index[c]);
  if (inconnus.length) incidents.push('faits inconnus cités : ' + inconnus.join(', '));
  if (cites.length < 2) incidents.push('moins de deux faits valides cités');
  const enonceSansCodes = String(h.enonce || '').replace(/\[?F\d+\]?/g, '');
  if (/\d/.test(enonceSansCodes)) incidents.push("chiffre étranger dans l'énoncé — les valeurs doivent rester dans les faits cités");
  if (!['haute','moyenne','basse'].includes(h.confiance)) { h.confiance = 'basse'; incidents.push('confiance absente, abaissée à basse'); }
  if (cites.length < 2) continue;   // sans deux faits, ce n'est pas une liaison : jeté et compté par l'écart de longueur
  sorties.push({ json: {
    run_id: prep.run_id,
    // normalisation déterministe : la consigne de style ne suffit pas toujours
    hypothese: String(h.enonce).replace(/\s+—\s+/g, ' : ').slice(0, 1200),
    faits_cites: JSON.stringify(Object.fromEntries(cites.map(c => [c, prep.faits_index[c]]))),
    confiance: h.confiance,
    infirmable_par: h.infirmable_par ? String(h.infirmable_par).slice(0, 400) : null,
    incidents: JSON.stringify(incidents),
    modele: $env.MODELE_ANTHROPIQUE || $env.MODELE_ANTHROPIC
  } });
}
if (!sorties.length) throw new Error('Aucune hypothèse exploitable rendue par le modèle.');
return sorties;

parameters.query:
INSERT INTO lectures_transversales (run_id, hypothese, faits_cites, confiance, infirmable_par, incidents, modele)
VALUES ($1,$2,$3::jsonb,$4,$5,$6::jsonb,$7)
RETURNING lecture_id;

UPDATE runs SET status='ok', closed_at=now(),
  note='Lecture transversale — ' || $2 || ' hypothèse(s) en attente de validation humaine.'
WHERE run_id=$1 RETURNING run_id, status, note;
